function option(x:string,locale:NativeLocale):string{
 const a=x.match(/^Article\s+(\d+(?:\([0-9A-Z]+\))?)$/);if(a)return (locale==="hi"?"अनुच्छेद ":"ਅਨੁਛੇਦ ")+a[1];
 if(/^\d+(?:%|\s+Ministers?)?$/.test(x))return x.replace(" Ministers",locale==="hi"?" मंत्री":" ਮੰਤਰੀ");
 const z=SPECIAL[x]??SIMPLE[x];if(z)return z[locale];
 throw new Error("POL-CP-015 missing localized option: "+x);
}

function localize(q:(typeof ENGLISH)[number],i:number,locale:PolLocaleV1):PolLocalizedQuestionV1{
 if(locale==="en")return {...q,chapterId:"POL-001",cpId:"POL-CP-015",qlName:q.qlId,reviewOnly:true,runtimeRegistered:false,options:[...q.options],locale,localizationV1:{version:POL_LOCALIZATION_V1,englishQuestionId:q.questionId,semanticInvariant:true,cpInvariant:true,qlInvariant:true,difficultyInvariant:true,sourceInvariant:true,optionOrderInvariant:true,correctIndexInvariant:true,reviewOnly:true}};
 let stem=STEMS[i]![locale],explanation=EXPS[i]![locale],options=q.options.map(x=>option(x,locale));
 if(locale==="pa"){stem=applyPolityPunjabiNativePassV1(stem);explanation=applyPolityPunjabiNativePassV1(explanation);options=options.map(applyPolityPunjabiNativePassV1);}
 return {...q,chapterId:"POL-001",cpId:"POL-CP-015",qlName:q.qlId,reviewOnly:true,runtimeRegistered:false,questionId:q.questionId+"-"+locale.toUpperCase(),stem,options,canonicalAnswer:options[q.correctIndex]!,explanation,locale,localizationV1:{version:POL_LOCALIZATION_V1,englishQuestionId:q.questionId,semanticInvariant:true,cpInvariant:true,qlInvariant:true,difficultyInvariant:true,sourceInvariant:true,optionOrderInvariant:true,correctIndexInvariant:true,reviewOnly:true}};
}
export function generatePolCp015LocalizedReviewV1(locale:PolLocaleV1):PolLocalizedQuestionV1[]{return ENGLISH.map((q,i)=>localize(q,i,locale));}
export const POL_CP015_LOCALIZATION_V1_ENGLISH_COUNT=ENGLISH.length;
